using namespace std;

class Solution {
public:
    long long minGeWithMask(long long x, long long mask) {
        if ((x & mask) == mask) return x;
        long long best = x | mask;
        long long cur_prefix = 0;
        for (int bit = 30; bit >= 0; bit--) {
            int mb = (mask >> bit) & 1;
            int xb = (x >> bit) & 1;
            if (mb == 1 && xb == 0) {
                long long cand = cur_prefix | (1LL << bit);
                for (int b = bit - 1; b >= 0; b--) {
                    if ((mask >> b) & 1) cand |= (1LL << b);
                }
                if (cand >= x && cand < best) best = cand;
                cur_prefix |= (1LL << bit);
            } else if (mb == 0 && xb == 0) {
                long long cand = cur_prefix | (1LL << bit);
                for (int b = bit - 1; b >= 0; b--) {
                    if ((mask >> b) & 1) cand |= (1LL << b);
                }
                if (cand >= x && cand < best) best = cand;
            } else {
                cur_prefix |= (1LL << bit);
            }
        }
        return best;
    }

    int maxBitwiseAnd(vector<int>& nums, int k) {
        long long ans = 0;
        for (int bit = 30; bit >= 0; bit--) {
            long long cand = ans | (1LL << bit);
            vector<long long> costs;
            for (int x : nums) costs.push_back(minGeWithMask(x, cand) - x);
            sort(costs.begin(), costs.end());
            if (costs[0] + costs[1] <= k) ans = cand;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private long minGeWithMask(long x, long mask) {
        if ((x & mask) == mask) return x;
        long best = x | mask;
        long curPrefix = 0;
        for (int bit = 30; bit >= 0; bit--) {
            int mb = (int)((mask >> bit) & 1);
            int xb = (int)((x >> bit) & 1);
            if (mb == 1 && xb == 0) {
                long cand = curPrefix | (1L << bit);
                for (int b = bit - 1; b >= 0; b--) {
                    if (((mask >> b) & 1) == 1) cand |= (1L << b);
                }
                if (cand >= x && cand < best) best = cand;
                curPrefix |= (1L << bit);
            } else if (mb == 0 && xb == 0) {
                long cand = curPrefix | (1L << bit);
                for (int b = bit - 1; b >= 0; b--) {
                    if (((mask >> b) & 1) == 1) cand |= (1L << b);
                }
                if (cand >= x && cand < best) best = cand;
            } else {
                curPrefix |= (1L << bit);
            }
        }
        return best;
    }

    public int maxBitwiseAnd(int[] nums, int k) {
        long ans = 0;
        for (int bit = 30; bit >= 0; bit--) {
            long cand = ans | (1L << bit);
            long[] costs = new long[nums.length];
            for (int i = 0; i < nums.length; i++) costs[i] = minGeWithMask(nums[i], cand) - nums[i];
            Arrays.sort(costs);
            if (costs[0] + costs[1] <= k) ans = cand;
        }
        return (int)ans;
    }
}

var maxBitwiseAnd = function(nums, k) {
    function minGeWithMask(x, mask) {
        const xB = BigInt(x), maskB = BigInt(mask);
        if ((xB & maskB) === maskB) return xB;
        let best = xB | maskB;
        let curPrefix = 0n;
        for (let bit = 30n; bit >= 0n; bit--) {
            const mb = (maskB >> bit) & 1n;
            const xb = (xB >> bit) & 1n;
            if (mb === 1n && xb === 0n) {
                let cand = curPrefix | (1n << bit);
                for (let b = bit - 1n; b >= 0n; b--) {
                    if ((maskB >> b) & 1n) cand |= (1n << b);
                }
                if (cand >= xB && cand < best) best = cand;
                curPrefix |= (1n << bit);
            } else if (mb === 0n && xb === 0n) {
                let cand = curPrefix | (1n << bit);
                for (let b = bit - 1n; b >= 0n; b--) {
                    if ((maskB >> b) & 1n) cand |= (1n << b);
                }
                if (cand >= xB && cand < best) best = cand;
            } else {
                curPrefix |= (1n << bit);
            }
        }
        return best;
    }
    let ans = 0n;
    for (let bit = 30n; bit >= 0n; bit--) {
        const cand = ans | (1n << bit);
        const costs = nums.map(x => Number(minGeWithMask(x, cand) - BigInt(x))).sort((a, b) => a - b);
        if (costs[0] + costs[1] <= k) ans = cand;
    }
    return Number(ans);
};
